ValidationRule.errorConditionFormula:
IF( $UserRole.Name = "System Administrator", FALSE, AND( OR(ISCHANGED(Status__c), ISCHANGED(Approval_Status__c)),
/* 範圍：Rejected（前/後）且完全排除 Reapplied（前/後） */ AND( OR( ISPICKVAL(Approval_Status__c, "Rejected"), ISPICKVAL(PRIORVALUE(Approval_Status__c), "Rejected") ), NOT( OR( TEXT(Status__c) = "Reapplied", TEXT(PRIORVALUE(Status__c)) = "Reapplied" ) ) ),
/* 白名單：0→5（不是未變更且不在清單就擋） */ NOT( OR( AND( TEXT(PRIORVALUE(Status__c)) = TEXT(Status__c), TEXT(PRIORVALUE(Approval_Status__c)) = TEXT(Approval_Status__c) ), CONTAINS( ";" & "New|New>In Progress|New;" & "In Progress|New>In Progress|In Progress;" & "In Progress|In Progress>In Progress|Rejected;" & "In Progress|Rejected>Replied|Rejected;" & "Replied|Rejected>Closed|Rejected;" & ";", ";" & TEXT(PRIORVALUE(Status__c)) & "|" & TEXT(PRIORVALUE(Approval_Status__c)) & ">" & TEXT(Status__c) & "|" & TEXT(Approval_Status__c) & ";" ) ) ) ) )
